# block-wizard's audio: carts/src/block-wizard/audio.json.
#   python3 carts/src/block-wizard/audio.py carts/src/block-wizard/audio.json
# Written by tools/devkit/music/script.py from the audio.json, so the music can be edited as text: instruments
# I00 to I1F are the slots, patterns and effects are tracker text (a row a line; a cell is "NNN II V FFF": note,
# instrument, volume, effect, as in the console's tracker), songs are order lists. Song toolkit: tools/devkit/music/kit.py.
# Eight songs, one for each room of the tower, and the effects in the numbers of SFX in code.js (each room has its own
# five, in the key of its song). The new sound chip (SPEC 5): a magical set of sampled instruments (a choir pad, celesta
# and flute leads, strings, a harp, a sampled bass), an echo for each room (deeper as the tower climbs), the leads
# (channel 0) an octave lower than they were written (up high a lead pierces); the songs use channels 0 to 5 and the
# effects take turns on 7 and 6. The notes and their timing are as they were: the game is synced to the music.
# After a change: node tools/devkit/music/loud.mjs carts/block-wizard.nova --check.
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '../../../tools/devkit/music'))
from kit import *

a = Audio(chip=2)

# --- Samples ---
a.samples.append({'rate': 16000, 'loop': None, 'data': ''})  # 0
a.samples.append({'rate': 16000, 'loop': None, 'data': ''})  # 1

# --- Instruments ---
a.voice('I00', 'flute', 5, -0.15)                       # the lead
a.voice('I01', 'bass', 12)                              # the bass
a.instrument('I02', 'noise-short', 0, 2, 0, 0, 5, (0, 0), 0.25, echo=2)   # the hats
a.instrument('I03', 'noise-short', 0, 7, 2, 4, 4, (0, 0), 0.25, echo=3)
a.instrument('I04', 'noise', 0, 6, 0, 0, 8, (0, 0), None, echo=4)
a.voice('I05', 'choir', 5, 0.2)                         # the pad: a choir
a.instrument('I06', 'pulse12', 0, 3, 0, 0, 9, (0, 0), None, echo=4)    # effects: blips
a.voice('I07', 'celesta', 12)                           # effects: chimes
a.voice('I08', 'tom', 12)                               # effects: thuds
a.voice('I09', 'celesta', 8, -0.1)                      # a bell lead
a.voice('I0A', 'marimba', 9, -0.1)                      # a staccato lead
a.voice('I0B', 'pluck', 12, 0.25, d=24)                 # the arpeggio
a.voice('I0C', 'flute', 4, -0.2, a=3)                   # a soft lead (room 4's)
a.voice('I0D', 'epiano', 7, 0.35, d=12)                 # short chords
a.voice('I0E', 'brass', 5)                              # a horn lead
a.voice('I0F', 'strings', 5)                            # held chords
a.voice('I10', 'brass', 5, -0.1)                        # the solo lead
a.instrument('I11', 'sample', 0, 0, 15, 0, 15, (0, 0), None, sample=0, echo=2)   # kick
a.instrument('I12', 'sample', 0, 0, 15, 0, 12, (0, 0), None, sample=1, echo=5)   # snare
a.voice('I13', 'strings', 5, 0.3)                       # the counter-melody

